import Foundation
import VEKit

/// Data-driven description of VE Configure's UI (tabs → pages → groups → controls), loaded from
/// `Resources/catalog.json` (generated by `tools/catalog.py` from the VE Configure 3 form, CHM help and the
/// reverse-engineered behaviour rules in docs/re/04-ui-rules.md).
final class Catalog {
    static let shared = Catalog()

    let tabs: [CatalogNode]
    let gridCodePages: [Int: GridPageChoice]
    let vsUsage: [Int: VSUsage]
    let batteryPresets: [BatteryPreset]
    let rules: [CatalogRule]
    let peerHandlers: [String: PeerHandlerInfo]

    /// Every control by Delphi name.
    private(set) var controls: [String: CatalogControl] = [:]
    /// Every group by Delphi name.
    private(set) var groups: [String: CatalogGroup] = [:]
    /// Device variable names (`EPROM_*`, `EBIT_*`, `pEBIT_*`, `RAM_*`) → reference.
    private(set) var variables: [String: VariableRef] = [:]
    /// First control bound directly to a setting / flag.
    private(set) var settingControls: [Int: CatalogControl] = [:]
    private(set) var flagControls: [Int: CatalogControl] = [:]
    /// Peer controls by the setting index of the grid word they view.
    private(set) var peerControlsBySetting: [Int: [CatalogControl]] = [:]
    /// The page (by name) each control sits on.
    private(set) var pageOfControl: [String: String] = [:]
    /// Every page (tab sheet) by name.
    private(set) var pages: [String: CatalogPage] = [:]
    let rulesByID: [String: CatalogRule]

    private init() {
        let file: CatalogFile
        do {
            // In the .app the catalog sits in Contents/Resources; Bundle.module is only for `swift run` builds.
            let inApp = Bundle.main.bundlePath.hasSuffix(".app")
            guard let url = Bundle.main.url(forResource: "catalog", withExtension: "json")
                ?? (inApp ? nil : Bundle.module.url(forResource: "catalog", withExtension: "json")) else {
                throw CocoaError(.fileNoSuchFile)
            }
            file = try JSONDecoder().decode(CatalogFile.self, from: Data(contentsOf: url))
        } catch {
            NSLog("VE Configure: cannot load catalog.json: \(error)")
            file = CatalogFile(tabs: [], gridCodePages: [:], vsUsage: [:], batteryPresets: [], rules: [], peerHandlers: [:])
        }
        tabs = file.tabs
        gridCodePages = Dictionary(uniqueKeysWithValues: file.gridCodePages.compactMap { k, v in
            guard let code = Int(k), let v else { return nil }
            return (code, GridPageChoice(spec: v))
        })
        vsUsage = Dictionary(uniqueKeysWithValues: file.vsUsage.compactMap { k, v in Int(k).map { ($0, v) } })
        batteryPresets = file.batteryPresets
        rules = file.rules
        rulesByID = Dictionary(file.rules.map { ($0.id, $0) }, uniquingKeysWith: { a, _ in a })
        peerHandlers = file.peerHandlers
        for tab in tabs { index(tab, page: nil) }
    }

    private func index(_ node: CatalogNode, page: String?) {
        switch node {
        case .page(let p):
            pages[p.name] = p
            for c in p.children { index(c, page: p.name) }
        case .pageControl(let pc):
            for p in pc.pages { index(.page(p), page: p.name) }
        case .group(let g):
            groups[g.name] = g
            for c in g.children { index(c, page: page) }
        case .control(let c):
            controls[c.name] = c
            if let page { pageOfControl[c.name] = page }
            if let v = c.variable, let name = v.name, let i = v.index { variables[name] = VariableRef(kind: v.kind, index: i, name: name) }
            if let v = c.variable, let i = v.index {
                if v.kind == .setting, settingControls[i] == nil { settingControls[i] = c }
                if v.kind == .flag, flagControls[i] == nil { flagControls[i] = c }
            }
            for p in c.peer?.peers ?? [] {
                if let v = p.variable, let name = v.name, let i = v.index { variables[name] = VariableRef(kind: v.kind, index: i, name: name) }
                if let i = p.variable?.index { peerControlsBySetting[i, default: []].append(c) }
            }
        }
    }

    // MARK: Public API used across the app

    func label(forSetting id: Int) -> String? {
        if let c = settingControls[id] { return c.changeListLabel }
        if (129...190).contains(id) {
            let word = id == 190 ? L("general") : "\(id - 129)"
            return L("Grid code parameter word %@", word)
        }
        if id == 128 || id == 191 { return L("Grid parameter checker %@", id == 128 ? "A" : "B") }
        return nil
    }

    /// Change-list label for a grid word, naming the controls that view it on the page in use.
    func label(forSetting id: Int, in config: DeviceConfiguration) -> String? {
        guard (129...190).contains(id), let page = GridPages.page(for: config) else { return label(forSetting: id) }
        let names = (peerControlsBySetting[id] ?? []).filter { pageOfControl[$0.name] == page }
            .compactMap { $0.changeListLabel }
        guard !names.isEmpty else { return label(forSetting: id) }
        let list = names.prefix(3).joined(separator: ", ") + (names.count > 3 ? "…" : "")
        return L("%@ (grid word %@)", list, id == 190 ? "G" : "\(id - 129)")
    }

    func label(forFlag n: Int) -> String? { flagControls[n]?.changeListLabel }

    func unit(forSetting id: Int) -> String? { settingControls[id]?.unit }

    func gridCodeName(_ index: Int) -> String? {
        guard let item = controls["GridCodeComboBox"]?.items?.first(where: { $0.value == index }) else { return nil }
        return L10n.catalog(GridCodes.clean(item.text.fallback))
    }

    /// The value of a flag as the user reads it on the control (inverted checkboxes, 50/60 Hz radios…).
    func formatFlag(_ n: Int, _ on: Bool) -> String {
        guard let c = flagControls[n] else { return on ? L("On") : L("Off") }
        if c.kind == .choice, let items = c.items {
            let raw = on ? 1 : 0
            if let item = items.first(where: { $0.matches(raw) }) { return L10n.catalog(Catalog.cleanCaption(item.displayText(context: nil))) }
        }
        let checked = c.semantics?.inverted == true ? !on : on
        return checked ? L("On") : L("Off")
    }
}

// MARK: - Decoded file

private struct CatalogFile: Decodable {
    var tabs: [CatalogNode]
    var gridCodePages: [String: String?]
    var vsUsage: [String: VSUsage]
    var batteryPresets: [BatteryPreset]
    var rules: [CatalogRule]
    var peerHandlers: [String: PeerHandlerInfo]
}

struct VariableRef: Hashable {
    var kind: VariableKind
    var index: Int
    var name: String
}

enum VariableKind: String, Decodable {
    case setting, flag, ram, peer
}

/// A caption that is either a literal or set at runtime (`variants` chosen by a `when` expression).
struct CatalogText: Decodable {
    var text: String?
    var variants: [Variant]?
    var dfmText: String?

    struct Variant: Decodable {
        var when: String?
        var text: String?
    }

    init(_ s: String) { text = s }

    init(from decoder: Decoder) throws {
        if let s = try? decoder.singleValueContainer().decode(String.self) {
            text = s
            return
        }
        let c = try decoder.container(keyedBy: Keys.self)
        text = try c.decodeIfPresent(String.self, forKey: .text)
        variants = try? c.decodeIfPresent([Variant].self, forKey: .variants)
        dfmText = try c.decodeIfPresent(String.self, forKey: .dfmText)
    }

    private enum Keys: String, CodingKey { case text, variants, dfmText }

    /// Text without evaluating variants: the literal, else the first variant.
    var fallback: String {
        if let text, !text.isEmpty { return text }
        return variants?.first(where: { ($0.text ?? "").isEmpty == false })?.text ?? ""
    }
}

indirect enum CatalogNode: Decodable {
    case page(CatalogPage)
    case pageControl(CatalogPageControl)
    case group(CatalogGroup)
    case control(CatalogControl)

    private enum Keys: String, CodingKey { case type }

    init(from decoder: Decoder) throws {
        let type = try decoder.container(keyedBy: Keys.self).decode(String.self, forKey: .type)
        switch type {
        case "page": self = .page(try CatalogPage(from: decoder))
        case "pageControl": self = .pageControl(try CatalogPageControl(from: decoder))
        case "group": self = .group(try CatalogGroup(from: decoder))
        default: self = .control(try CatalogControl(from: decoder))
        }
    }

    var name: String {
        switch self {
        case .page(let p): p.name
        case .pageControl(let p): p.name
        case .group(let g): g.name
        case .control(let c): c.name
        }
    }

    var frame: [Double]? {
        switch self {
        case .group(let g): g.frame
        case .control(let c): c.frame
        default: nil
        }
    }
}

struct CatalogPage: Decodable {
    var name: String
    var caption: CatalogText?
    var help: HelpTopic?
    var children: [CatalogNode]
}

struct CatalogPageControl: Decodable {
    var name: String
    var pages: [CatalogPage]
}

struct CatalogGroup: Decodable {
    enum Kind: String, Decodable { case groupBox, panel, scroll, frame }
    var kind: Kind
    var name: String
    var caption: CatalogText?
    var tag: Int?
    var frame: [Double]?
    var visibleAtDesign: Bool?
    var enabledWhen: [String]?
    var visibleWhen: [String]?
    var children: [CatalogNode]
}

struct HelpTopic: Decodable {
    var id: Int?
    var title: String?
    var text: String?
}

struct CatalogControl: Decodable {
    enum Kind: String, Decodable {
        case number, toggle, choice, readout, button, text, localToggle, localChoice, localText, canvas, list, progress, link
        case unknown
    }

    struct Variable: Decodable {
        var kind: VariableKind
        var index: Int?
        var name: String?
    }

    struct Peer: Decodable {
        var control: String
        var mask: Int
        var shift: Int
        var width: Int
        var variable: Variable?
    }

    struct Codec: Decodable {
        var scale: Double
        var offset: Double
        var signBit: Int?
        var reciprocal: Bool?
        var offsetBeforeInvert: Bool?
        var min: Double?
        var max: Double?
        var `default`: Double?
        var precision: Int?
    }

    struct PeerSpec: Decodable {
        var peers: [Peer]
        var codec: Codec
        var custom: Bool?
    }

    struct Item: Decodable {
        var text: CatalogText
        var value: Int?
        var values: [Int]?
        var hidden: Bool?
        var plusMarked: Bool?
        var runtimeText: [CatalogText.Variant]?

        func matches(_ raw: Int) -> Bool { (values ?? [value ?? -1]).contains(raw) }

        func displayText(context: RuleContext?) -> String {
            if let runtimeText, !runtimeText.isEmpty {
                if let context, let v = runtimeText.first(where: { $0.when.map { context.evaluate($0) == true } ?? false }), let t = v.text {
                    return t
                }
                if let t = runtimeText.first?.text { return t }
            }
            return text.fallback
        }
    }

    struct Semantics: Decodable {
        var precision: Int?
        var inverted: Bool?
        var linkedControl: String?

        init(from decoder: Decoder) throws {
            let c = try decoder.container(keyedBy: Keys.self)
            precision = try? c.decodeIfPresent(Int.self, forKey: .precision)
            inverted = try? c.decodeIfPresent(Bool.self, forKey: .inverted)
            linkedControl = try? c.decodeIfPresent(String.self, forKey: .linkedControl)
        }
        private enum Keys: String, CodingKey { case precision, inverted, linkedControl }
    }

    struct Event: Decodable { var handler: String }

    struct Label: Decodable {
        var text: CatalogText?
        var position: String?
    }

    var kind: Kind
    var name: String
    var `class`: String?
    var tag: Int?
    var frame: [Double]?
    var caption: CatalogText?
    var label: CatalogText?
    var labels: [Label]?
    var description: String?
    var unit: String?
    var help: HelpTopic?
    var text: String?
    var variable: Variable?
    var peer: PeerSpec?
    var items: [Item]?
    var semantics: Semantics?
    var events: [String: Event]?
    var enabledWhen: [String]?
    var visibleWhen: [String]?
    var rules: [String]?
    var visibleAtDesign: Bool?

    private enum Keys: String, CodingKey {
        case kind, name, `class`, tag, frame, caption, label, labels, description, unit, help, text, variable, peer, items
        case semantics, events, enabledWhen, visibleWhen, rules, visibleAtDesign
    }

    init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: Keys.self)
        kind = (try? c.decode(Kind.self, forKey: .kind)) ?? .unknown
        name = try c.decode(String.self, forKey: .name)
        `class` = try? c.decodeIfPresent(String.self, forKey: .class)
        tag = try? c.decodeIfPresent(Int.self, forKey: .tag)
        frame = try? c.decodeIfPresent([Double].self, forKey: .frame)
        caption = try? c.decodeIfPresent(CatalogText.self, forKey: .caption)
        label = try? c.decodeIfPresent(CatalogText.self, forKey: .label)
        labels = try? c.decodeIfPresent([Label].self, forKey: .labels)
        description = try? c.decodeIfPresent(String.self, forKey: .description)
        unit = try? c.decodeIfPresent(String.self, forKey: .unit)
        help = try? c.decodeIfPresent(HelpTopic.self, forKey: .help)
        text = try? c.decodeIfPresent(String.self, forKey: .text)
        variable = try? c.decodeIfPresent(Variable.self, forKey: .variable)
        peer = try? c.decodeIfPresent(PeerSpec.self, forKey: .peer)
        items = try? c.decodeIfPresent([Item].self, forKey: .items)
        semantics = try? c.decodeIfPresent(Semantics.self, forKey: .semantics)
        events = try? c.decodeIfPresent([String: Event].self, forKey: .events)
        enabledWhen = try? c.decodeIfPresent([String].self, forKey: .enabledWhen)
        visibleWhen = try? c.decodeIfPresent([String].self, forKey: .visibleWhen)
        rules = try? c.decodeIfPresent([String].self, forKey: .rules)
        visibleAtDesign = try? c.decodeIfPresent(Bool.self, forKey: .visibleAtDesign)
    }

    func handler(_ event: String) -> String? { events?[event]?.handler }

    var isInverted: Bool { semantics?.inverted == true }

    /// Label text without runtime context.
    var staticLabel: String? {
        let t = (label ?? caption)?.fallback
        return t.map(Catalog.cleanCaption).flatMap { $0.isEmpty ? nil : $0 }
    }

    /// LongSettingDescription, without Delphi format placeholders, in the interface language.
    var cleanDescription: String? {
        guard var d = description, !d.isEmpty else { return nil }
        if d.hasPrefix("|") { return nil }
        if let bar = d.firstIndex(of: "|") { d = String(d[..<bar]) }
        d = d.replacingOccurrences(of: "%s", with: "").replacingOccurrences(of: "%0:s", with: "")
            .replacingOccurrences(of: "%1:s", with: "")
        d = d.trimmingCharacters(in: .whitespaces)
        return d.isEmpty ? nil : L10n.catalog(Catalog.cleanCaption(d.prefix(1).uppercased() + d.dropFirst()))
    }

    /// Label used in the change list (interface language): the visible label unless it is only a fragment ("for").
    var changeListLabel: String? {
        if let l = staticLabel, l.count > 4, !l.hasSuffix(" for") { return L10n.catalog(l) }
        return cleanDescription ?? L10n.catalog(staticLabel ?? help?.title)
    }

    /// Settings this control writes (direct variable, grid words, or for a local control the settings it sets).
    var settingTargets: [Int] {
        if let v = variable, v.kind == .setting, let i = v.index { return [i] }
        if kind == .localToggle || kind == .localChoice { return LocalControls.writtenControls(name).flatMap(\.settingTargets) }
        return peer?.peers.compactMap { $0.variable?.index } ?? []
    }
}

struct CatalogRule: Decodable {
    var id: String
    var kind: String
    var targets: [String]
    var expr: String?
    var message: String?
    var notes: String?
}

struct PeerHandlerInfo: Decodable {
    var read: String?
    var write: String?
    var uncertain: Bool?
}

struct VSUsage: Decodable {
    var label: String
    var labelInverted: String?
}

struct BatteryPreset: Decodable, Identifiable {
    struct Value: Decodable {
        var value: Double
        var unit: String?
        var normalisedTo12V: Bool?
    }
    struct Flags: Decodable {
        var clearsTubularPlate: Bool?
        var requiresVEBusBMSSupport: Bool?
    }
    var id: String
    var name: String
    var values: [String: Value]
    var notSet: [String]?
    var flags: Flags?
}

/// `gridCodePages` entry: "AS4777GridCodePage|variant!=0:NewAS4777GridCodePage".
struct GridPageChoice {
    var base: String
    var alternatives: [(op: String, value: Int, page: String)]

    init(spec: String) {
        let parts = spec.split(separator: "|").map(String.init)
        base = parts.first ?? spec
        alternatives = parts.dropFirst().compactMap { alt in
            guard let colon = alt.firstIndex(of: ":") else { return nil }
            let cond = alt[..<colon].replacingOccurrences(of: "variant", with: "")
            let page = String(alt[alt.index(after: colon)...])
            for op in [">=", "<=", "!=", "==", ">", "<"] where cond.hasPrefix(op) {
                if let v = Int(cond.dropFirst(op.count)) { return (op, v, page) }
            }
            return nil
        }
    }

    func page(variant: Int) -> String {
        for a in alternatives {
            let hit: Bool
            switch a.op {
            case ">=": hit = variant >= a.value
            case "<=": hit = variant <= a.value
            case "!=": hit = variant != a.value
            case "==": hit = variant == a.value
            case ">": hit = variant > a.value
            default: hit = variant < a.value
            }
            if hit { return a.page }
        }
        return base
    }
}

extension Catalog {
    /// Removes Delphi accelerators and caption padding.
    static func cleanCaption(_ s: String) -> String {
        var t = s.replacingOccurrences(of: "&&", with: "\u{1}").replacingOccurrences(of: "&", with: "")
            .replacingOccurrences(of: "\u{1}", with: "&")
        t = t.replacingOccurrences(of: "\r", with: " ").replacingOccurrences(of: "\n", with: " ")
        while t.contains("  ") { t = t.replacingOccurrences(of: "  ", with: " ") }
        t = t.trimmingCharacters(in: .whitespaces)
        if t.hasSuffix(":") { t.removeLast() }
        return t.trimmingCharacters(in: .whitespaces)
    }

    /// CHM help text reflowed: hard wraps joined, short lines (lists, headings) kept.
    static func reflow(_ s: String) -> String {
        let lines = s.replacingOccurrences(of: "\r", with: "").components(separatedBy: "\n")
        var out = ""
        for (i, line) in lines.enumerated() {
            let l = line.trimmingCharacters(in: .whitespaces)
            if i == 0 { out = l; continue }
            let prev = lines[i - 1].trimmingCharacters(in: .whitespaces)
            if l.isEmpty { out += "\n\n"; continue }
            let breakLine = prev.isEmpty || prev.count < 28 && (prev.last.map { ".:!?".contains($0) } ?? false || l.first?.isUppercase == true)
            out += breakLine ? "\n" + l : " " + l
        }
        while out.contains("\n\n\n") { out = out.replacingOccurrences(of: "\n\n\n", with: "\n\n") }
        return out
    }
}

extension GridCodes {
    /// "09_France:                UTE C15-712-1:2013-07" → "France: UTE C15-712-1:2013-07".
    static func clean(_ s: String) -> String {
        var t = s
        if t.count > 3, t.dropFirst(2).first == "_", Int(t.prefix(2)) != nil { t = String(t.dropFirst(3)) }
        t = Catalog.cleanCaption(t)
        guard let r = t.range(of: ":") else { return t }
        let name = t[..<r.lowerBound].trimmingCharacters(in: .whitespaces)
        let rest = t[r.upperBound...].trimmingCharacters(in: .whitespaces)
        return rest.isEmpty ? name : "\(name) — \(rest)"
    }
}
